import http from "node:http";
import { SSEServerTransport } from "@modelcontextprotocol/sdk/server/sse.js";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";

const mcpServer = new McpServer(
  {
    name: "Test",
    version: "0.0.1",
  },
);

const toolDescription = "testing server";
const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

mcpServer.tool(
  "test",
  toolDescription,
  { my_arg: z.string().describe("testing") },
  async ({ my_arg }: { my_arg: string }) => {
    console.log({ my_arg });
    await sleep(1000);
    return {
      content: [{ type: "text", text: "success" }],
    };
  },
);
const transports: { [sessionId: string]: SSEServerTransport } = {};

const server = http.createServer(async (req, res) => {
  const url = new URL(
    req.url ?? "",
    `http://${req.headers.host ?? "unknown"}`,
  );

  let pathMatch = false;
  function match(method: string, path: string): boolean {
    if (url.pathname === path) {
      pathMatch = true;
      return req.method === method;
    }
    return false;
  }

  if (match("GET", "/sse")) {
    const transport = new SSEServerTransport("/sse", res);
    transports[transport.sessionId] = transport;
    res.on("close", () => {
      delete transports[transport.sessionId];
    });
    await mcpServer.connect(transport);
  } else if (match("POST", "/messages")) {
    const sessionId = url.searchParams.get("sessionId") ?? "";
    const transport = transports[sessionId];
    if (transport) {
      await transport.handlePostMessage(req, res);
    } else {
      res.setHeader("Content-Type", "text/plain");
      res.statusCode = 400;
      res.end(`No transport found for sessionId '${sessionId}'`);
    }
  } else {
    res.setHeader("Content-Type", "text/plain");
    res.statusCode = pathMatch ? 405 : 404;
    res.end(pathMatch ? "Method not allowed\n" : "Page not found\n");
  }
});

const port = 3001;
server.listen(port, () => {
  console.log(`Running MCP server with SSE transport on port ${port}`);
});
